<template>
  <div class="projects-shell" :class="`track-${activeTrack}`">
    <div class="project-backdrop" aria-hidden="true">
      <div class="project-bg"></div>
      <div class="project-bg project-bg-2"></div>
      <div class="project-bg project-bg-3"></div>
    </div>

    <section class="projects-hero">
      <p class="mono-label">Selected systems and shipped experiences</p>
      <h1>Browse through my work over the last years.</h1>
      <p>
        From engineering endeavors to shipping real games, my history reflects my unique
        technical design identity. <router-link to="/about">Read more about that approach.</router-link>
      </p>
      <div class="track-controls">
        <button
          v-for="track in trackList"
          :key="track.id"
          :class="[`track-control-${track.id}`, { active: activeTrack === track.id }]"
          type="button"
          @click="setTrack(track.id)"
        >
          <span>{{ track.shortLabel }}</span>
          <small>{{ track.label }}</small>
        </button>
      </div>
    </section>

    <section class="projects-grid">
      <article
        v-for="project in orderedProjects"
        :key="project.slug"
        class="project-card"
        :class="projectCardClass(project)"
      >
        <div class="project-media">
          <img :src="project.image" :alt="project.title">
          <div v-if="project.isConfidential" class="nda-card-overlay" aria-label="NDA protected project">
            <span class="lock-icon" aria-hidden="true"></span>
            <strong>NDA</strong>
          </div>
          <p v-if="project.imageCaption" class="image-caption">{{ project.imageCaption }}</p>
          <div class="track-badges">
            <span
              v-for="track in project.tracks"
              :key="track"
              :class="`track-badge-${track}`"
            >
              {{ tracks[track].shortLabel }}
            </span>
          </div>
        </div>
        <div class="project-content">
          <div>
            <p class="mono-label">{{ project.role }}</p>
            <h2>{{ project.title }}</h2>
            <p class="company">{{ project.companyLocation }} / {{ project.period }}</p>
          </div>
          <p v-html="project.summaryHtml || project.summary"></p>
          <p class="relevance" v-html="project.relevanceHtml || project.relevance"></p>
          <div class="tag-row">
            <span v-for="tag in project.tags" :key="tag">{{ tag }}</span>
          </div>
          <div class="highlight-panel">
            <strong>{{ project.highlightTitle }}</strong>
            <ul>
              <li v-for="item in project.highlights" :key="item">{{ item }}</li>
            </ul>
          </div>
          <div class="actions">
            <router-link :to="`/project/${project.slug}`">{{ project.detailLabel || 'Project details' }}</router-link>
            <a
              v-for="link in project.links"
              :key="link.url"
              :href="link.url"
              target="_blank"
              rel="noopener"
            >
              {{ link.label }}
            </a>
          </div>
        </div>
      </article>
    </section>
  </div>
</template>

<script>
import portfolio from '@/services/portfolio'

export default {
  data: () => ({
    activeTrack: 'all',
    tracks: portfolio.tracks
  }),
  computed: {
    allTrack() {
      return {
        id: 'all',
        shortLabel: 'All',
        label: 'All projects'
      }
    },
    trackList() {
      return [this.allTrack, this.tracks.engineering, this.tracks.games]
    },
    orderedProjects() {
      return portfolio.getProjectsForTrack(this.activeTrack)
    }
  },
  watch: {
    '$route.query.track': {
      immediate: true,
      handler(track) {
        if (track === 'games' || track === 'engineering') {
          this.activeTrack = track
        } else {
          this.activeTrack = 'all'
        }
      }
    }
  },
  methods: {
    projectCardClass(project) {
      const primaryTrack = project.tracks?.[0]
      return {
        'project-card-games': this.activeTrack === 'all' && primaryTrack === 'games',
        'project-card-engineering': this.activeTrack === 'all' && primaryTrack === 'engineering',
        'project-card-nda': project.isConfidential
      }
    },
    setTrack(track) {
      this.activeTrack = track
      if (track === 'all') {
        const query = { ...this.$route.query }
        delete query.track
        this.$router.replace({ query }).catch(() => {})
      } else if (this.$route.query.track !== track) {
        this.$router.replace({ query: { ...this.$route.query, track } }).catch(() => {})
      }
    }
  }
}
</script>

<style scoped>
