  display: grid;
  place-content: center;
  justify-items: center;
  gap: 6px;
  background:
    radial-gradient(circle at 50% 45%, rgba(var(--palette-bg-rgb), 0.28), rgba(var(--palette-bg-rgb), 0.7)),
    linear-gradient(135deg, rgba(var(--palette-accent-rgb), 0.15), rgba(var(--palette-bg-rgb), 0.32));
